const main = document.getElementById('main');
const storageKey = 'maths-club-progress-v1';
let storageAvailable = true;
let progress = {};
try {
  const stored = JSON.parse(localStorage.getItem(storageKey) || '{}');
  for (const grade of [6,7,8,9]) for(let level=1;level<=3;level++) {
    const key = `${grade}-${level}`, value = stored?.[key];
    if(value && Array.isArray(value.answers) && value.answers.length === 5 && value.answers.every(a => a === null || (Number.isInteger(a) && a >= 0 && a < 4))) {
      progress[key] = {answers:value.answers,submitted:value.submitted === true && value.answers.every(a=>a!==null),best:Number.isInteger(value.best)?Math.min(5,Math.max(0,value.best)):0,attempts:Number.isInteger(value.attempts)?Math.max(0,value.attempts):0};
    }
  }
} catch { storageAvailable = false; }
function saveProgress() {try{localStorage.setItem(storageKey,JSON.stringify(progress));}catch{storageAvailable=false;}updateStorageNote();}
function updateStorageNote(){document.getElementById('storage-note').textContent = storageAvailable ? 'Your progress stays in this browser. No account needed.' : 'Progress is saved for this visit. Browser storage is unavailable.';}
function stateFor(g,l){return progress[`${g}-${l}`] ||= {answers:Array(5).fill(null),submitted:false,best:0,attempts:0};}
function scoreFor(g,l){const s=stateFor(g,l);return CURRICULUM[g].levels[l-1].questions.reduce((n,q,i)=>n+(s.answers[i]===q.answer?1:0),0);}
function practised(g){return [1,2,3].filter(l=>stateFor(g,l).attempts>0).length;}
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const goArrow = '<span class="arrow" aria-hidden="true">→</span>';
function button(href,text,secondary=false){return `<a class="button${secondary?' secondary':''}" href="${href}">${text}${goArrow}</a>`;}
function gradeIcon(g){
  const icons={
    6:'<rect x="5" y="5" width="19" height="19" rx="3" fill="#69a68d"/><rect x="28" y="5" width="19" height="19" rx="3" fill="#94c5ad"/><rect x="5" y="28" width="19" height="19" rx="3" fill="#94c5ad"/><rect x="28" y="28" width="19" height="19" rx="3" fill="#69a68d"/>',
    7:'<path d="M7 43 25 6l20 37Z" fill="#e8a07e"/><path d="M24 43 43 6l10 37Z" fill="#d77c59" opacity=".65"/><path d="M16 38 25 18l10 20Z" fill="#f9ded0"/>',
    8:'<circle cx="26" cy="26" r="22" fill="#9c83cb"/><path d="M26 4v22h22A22 22 0 0 0 26 4" fill="#c1ace8"/><path d="M26 26v22A22 22 0 0 1 4 26Z" fill="#b79dde"/><circle cx="26" cy="26" r="9" fill="#e9e1f8"/>',
    9:'<path d="m26 1 6 14 15-5-5 15 12 8-16 3 1 16-13-9-13 9 1-16L0 33l12-8-5-15 15 5Z" fill="#d7b85c"/><circle cx="26" cy="27" r="9" fill="#f7ecc7"/>'
  };
  return `<span class="card-symbol" aria-hidden="true"><svg viewBox="0 0 54 54">${icons[g]}</svg></span>`;
}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 550 425" fill="none" xmlns="http://www.w3.org/2000/svg">
  <defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0v24" stroke="#ddd7e8" stroke-width=".7"/></pattern><pattern id="dotgrid" width="11" height="11" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#c6bfce"/></pattern><linearGradient id="ruler" x1="305" y1="210" x2="450" y2="345" gradientUnits="userSpaceOnUse"><stop stop-color="#ee977a"/><stop offset="1" stop-color="#e87a60"/></linearGradient></defs>
  <circle cx="293" cy="209" r="174" fill="#f0ebe2"/>
  <circle cx="95" cy="110" r="34" fill="url(#dotgrid)"/>
  <path d="m481 133 6-17 6 17 17 6-17 6-6 17-6-17-17-6Z" fill="#aa94d3"/>
  <path d="m96 297 4-11 4 11 11 4-11 4-4 11-4-11-11-4Z" fill="#dab963"/>
  <g transform="rotate(-9 270 199)"><rect x="135" y="68" width="279" height="279" rx="12" fill="#d7cfc2" opacity=".3" transform="translate(3 7)"/><rect x="135" y="68" width="279" height="279" rx="12" fill="#fffcf8"/><rect x="147" y="80" width="255" height="255" rx="6" fill="url(#grid)"/><path d="M180 298V127m-6 7 6-8 6 8M180 298h184m-7-6 8 6-8 6" stroke="#bcb3cb" stroke-width="1.6" stroke-linecap="round"/><path d="m192 278 43-32 37-7 38-65 48-39" stroke="#8c6bcb" stroke-width="4" stroke-linecap="round"/><circle cx="235" cy="246" r="5" fill="#8c6bcb"/><circle cx="272" cy="239" r="5" fill="#8c6bcb"/><circle cx="310" cy="174" r="5" fill="#8c6bcb"/><text x="220" y="147" fill="#786295" font-family="Georgia,serif" font-size="23" font-style="italic">y = 2x + you</text></g>
  <g class="float"><circle cx="409" cy="78" r="43" fill="#efcf6c"/><path d="M409 48v60m-30-30h60m-51-21 42 42m0-42-42 42" stroke="#d7ac40" stroke-width="2"/><circle cx="409" cy="78" r="17" fill="#f6dc87"/><path d="m401 77 6 6 11-12" stroke="#8b6e2c" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></g>
  <g transform="rotate(11 144 218)"><path d="M83 203a65 65 0 0 1 130 0v55H83Z" fill="#7960b4"/><path d="M101 203a47 47 0 0 1 94 0v55h-94Z" fill="#a58ad6"/><path d="M119 203a29 29 0 0 1 58 0v55h-58Z" fill="#c6b0e8"/><path d="M137 203a11 11 0 0 1 22 0v55h-22Z" fill="#faf7f2"/><path d="M83 243h54m22 0h54M83 226h54m22 0h54M148 138v47m-35-37 24 43m46-43-24 43" stroke="#f8f1ff" stroke-opacity=".35"/></g>
  <g transform="rotate(12 365 295)"><path d="M303 209v151h154L303 209Z" fill="url(#ruler)"/><path d="M328 270v65h65l-65-65Z" fill="#f5eee6"/><path d="M311 229h9m-9 15h6m-6 15h9m-9 15h6m-6 15h9m-9 15h6m-6 15h9m-9 15h6m14 17v-7m15 7v-5m15 5v-7m15 7v-5m15 5v-7m15 7v-5" stroke="#bb5d47" stroke-width="1.3"/><circle cx="316" cy="347" r="3" fill="#bb5d47"/></g>
  <g class="float-slow"><rect x="54" y="319" width="167" height="46" rx="11" fill="#fffefa" stroke="#ebe5dc"/><circle cx="78" cy="342" r="11" fill="#e2eee7"/><path d="m73 342 4 4 6-7" stroke="#6c9b7b" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><text x="98" y="347" fill="#5a5266" font-family="Arial,sans-serif" font-size="12" font-weight="600">You've got this!</text></g>
  <g transform="rotate(-12 443 215)"><rect x="414" y="185" width="60" height="60" rx="17" fill="#b2d8c5"/><path d="m433 204 21 21m0-21-21 21" stroke="#4e8e74" stroke-width="5" stroke-linecap="round"/></g>
  <path d="m245 30 5-12 5 12 12 5-12 5-5 12-5-12-12-5Z" fill="#e99a7d"/>
  <path d="m450 366 7-6m-1 17h10m-20-2 2 9" stroke="#a48bc7" stroke-width="2" stroke-linecap="round"/>
  <text x="65" y="83" fill="#9a87b5" font-family="Georgia,serif" font-size="27" font-style="italic" transform="rotate(-15 65 83)">a²</text><text x="448" y="310" fill="#c9ab64" font-family="Georgia,serif" font-size="25" transform="rotate(15 448 310)">π</text>
</svg></div>`;}
function gradeCards(){return `<div class="grade-grid">${[6,7,8,9].map(g=>{const c=CURRICULUM[g],done=practised(g);return `<a class="grade-card ${c.theme}" href="#/grade/${g}" aria-label="Explore Grade ${g}"><div class="card-top">${gradeIcon(g)}<span class="count-badge">3 levels</span></div><h3>Grade ${g}</h3><p>${c.topics}</p><div class="card-bottom"><span>${done?`${done}/3 levels practised`:'Let’s explore'}</span><span class="circle-arrow" aria-hidden="true">↗</span></div></a>`;}).join('')}</div>`;}
function home(){return `<div class="container"><section class="hero"><div class="hero-copy"><span class="pill"><span aria-hidden="true">✦</span> FOR CURIOUS MINDS, GRADES 6–9</span><h1>Small steps.<br>Big <em>discoveries.<svg class="hero-underline" viewBox="0 0 390 13" preserveAspectRatio="none" aria-hidden="true"><path d="M3 8Q180-4 386 5M14 12Q200 4 360 10" stroke="currentColor" stroke-width="3" stroke-linecap="round" fill="none"/></svg></em></h1><p>A little curiosity goes a long way. Explore bite-sized lessons, try a challenge, and find your “I get it!” moment.</p><div class="hero-actions">${button('#/grades','Find your grade')}<span><span class="mini-check">✓</span> Learn at your own pace</span></div><div class="hero-footnote"><span>4 grades</span><i></i><span>12 levels to explore</span><i></i><span>Endless lightbulb moments</span></div></div>${heroArt()}</section><section class="grades-section" aria-labelledby="grades-title"><div class="section-heading"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h2 id="grades-title">Where shall we start?</h2></div><p>Pick your grade. Find your spark.</p></div>${gradeCards()}</section><section class="path-section"><div class="path-heading"><h2>A little learning. A little doing. A lot of growing.</h2><p>Three simple steps to a more confident you.</p></div><div class="path-grid"><div class="path-step"><span class="step-icon" aria-hidden="true">▤</span><div><h3>01. Get the idea</h3><p>Clear explanations and worked examples make tricky things click.</p></div></div><div class="path-step"><span class="step-icon" aria-hidden="true">✎</span><div><h3>02. Give it a go</h3><p>Put your thinking to work with five questions in every level.</p></div></div><div class="path-step"><span class="step-icon" aria-hidden="true">✧</span><div><h3>03. Watch yourself grow</h3><p>Check your answers, learn from feedback, and try again.</p></div></div></div></section><section class="challenge-strip"><span class="challenge-spark" aria-hidden="true">✦</span><div><h3>Every “aha!” starts with a “what if?”</h3><p>What if you gave algebra a go? A five-question challenge is waiting.</p></div><a href="#/grade/7/level/1/exercises">Try a little challenge ${goArrow}</a></section></div>`;}
function crumbs(items){return `<div class="breadcrumbs"><a href="#/">Home</a>${items.map(([label,href])=>`<span aria-hidden="true">/</span>${href?`<a href="${href}">${label}</a>`:`<span>${label}</span>`}`).join('')}</div>`;}
function grades(){return `<div class="container">${crumbs([['Grades']])}<section class="page-intro"><span class="eyebrow">FIND YOUR STARTING POINT</span><h1>A new discovery<br>at every grade.</h1><p>Choose a grade to explore three levels of maths. Start wherever you feel ready — you can always revisit an idea or try something new.</p></section><section class="grades-section">${gradeCards()}</section><div class="challenge-strip"><span class="challenge-spark" aria-hidden="true">✧</span><div><h3>There’s no rush to get it right.</h3><p>Every level comes with an explanation, five questions, and feedback to help you grow.</p></div></div></div>`;}
function gradePage(g){const c=CURRICULUM[g],done=practised(g);return `<div class="container">${crumbs([['Grades','#/grades'],[`Grade ${g}`]])}<section class="grade-intro ${c.theme}"><div><span class="eyebrow">${c.name}</span><h1>Hello, Grade ${g}<span class="brand-dot">.</span></h1><p>${c.description}</p><div class="grade-progress"><div class="progress-track" role="progressbar" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="3" aria-label="Levels practised"><span style="width:${done/3*100}%"></span></div><span>${done} of 3 levels practised</span></div></div><div class="grade-intro-art">${gradeIcon(g)}</div></section><section><div class="section-heading"><div><span class="eyebrow">ONE STEP AT A TIME</span><h2>Choose your next challenge.</h2></div><p>Start with Level 1, or follow your curiosity.</p></div><div class="level-grid">${c.levels.map((l,i)=>{const state=stateFor(g,i+1);return `<article class="level-card"><div class="level-no"><span>${i+1}</span> LEVEL ${i+1}</div><h3>${l.title}</h3><p>${l.tagline}</p><div class="level-meta"><span>▤ &nbsp;1 lesson</span><span>✎ &nbsp;5 questions</span></div>${state.attempts?`<div class="best-label">${state.best===5?'✦ All five — brilliant!':'✓ You’ve given this a go'} · Best ${state.best}/5</div>`:''}${button(`#/grade/${g}/level/${i+1}/content`,state.attempts?'Explore again':'Start Level '+(i+1),i!==0)}</article>`;}).join('')}</div></section><p class="gentle-note"><span aria-hidden="true">✧</span> Every level is open. Learn, practise, and try again as often as you like.</p></div>`;}
function levelShell(g,l,tab,body){const lesson=CURRICULUM[g].levels[l-1];return `<div class="container">${crumbs([['Grades','#/grades'],[`Grade ${g}`,`#/grade/${g}`],[`Level ${l}`]])}<section class="level-header"><span class="eyebrow">GRADE ${g} <span aria-hidden="true">·</span> LEVEL ${l}</span><h1>${lesson.title}</h1><p>${lesson.tagline}</p></section><nav class="level-tabs" aria-label="Level sections">${[['content','Content'],['exercises','Exercises'],['results','Results & feedback']].map(([key,label],i)=>`<a href="#/grade/${g}/level/${l}/${key}" class="${key===tab?'active':''}"${key===tab?' aria-current="page"':''}><span class="tab-number">${i+1}</span>${label}</a>`).join('')}</nav>${body}</div>`;}
function contentPage(g,l){const lesson=CURRICULUM[g].levels[l-1];return levelShell(g,l,'content',`<div class="lesson-layout"><article class="lesson-main"><span class="eyebrow">LET’S MAKE IT CLICK</span><h2>The idea, in a nutshell.</h2><p class="intro">${lesson.intro}</p>${lesson.rules.map(([title,copy],i)=>`<section class="lesson-rule"><span class="rule-number">${i+1}</span><div><h3>${title}</h3><p>${copy}</p></div></section>`).join('')}${button(`#/grade/${g}/level/${l}/exercises`,'I’m ready. Let’s practise!')}</article><aside class="lesson-aside"><span class="eyebrow">A LITTLE WALK-THROUGH</span><h3>${lesson.example.problem}</h3>${lesson.example.steps.map((s,i)=>`<p class="example-step"><strong>${i+1}.</strong> ${s}</p>`).join('')}<div class="example-answer">${lesson.example.answer}</div><p class="example-step">One step at a time. You’ve got this.</p></aside></div>`);}
function exercisePage(g,l){const lesson=CURRICULUM[g].levels[l-1],state=stateFor(g,l),count=state.answers.filter(a=>a!==null).length;return levelShell(g,l,'exercises',`<div class="quiz-form"><div class="exercise-top"><div><h2>Time to give it a go.</h2><p>Choose one answer for each question. Take your time.</p></div><span class="answered-counter" id="answered-counter">${count} of 5 answered</span></div>${state.submitted?`<div class="completed-banner"><span>✓ You scored <strong>${scoreFor(g,l)} out of 5</strong>. Every attempt is a step forward.</span><a href="#/grade/${g}/level/${l}/results">See your results →</a></div>`:''}<form id="quiz" data-grade="${g}" data-level="${l}" novalidate><div id="quiz-validation" role="alert"></div>${lesson.questions.map((q,i)=>`<fieldset class="question-card" id="question-${i}"><legend><span class="question-num">${i+1}</span><span>${q.prompt}</span></legend><div class="question-options">${q.options.map((option,j)=>`<label class="option${state.answers[i]===j?' selected':''}${state.submitted&&q.answer===j?' correct':''}${state.submitted&&state.answers[i]===j&&q.answer!==j?' incorrect':''}"><input type="radio" name="q${i}" value="${j}" data-question="${i}" ${state.answers[i]===j?'checked':''} ${state.submitted?'disabled':''} required><span class="option-letter" aria-hidden="true">${state.submitted&&j===q.answer?'✓':String.fromCharCode(65+j)}</span><span>${option}</span></label>`).join('')}</div>${state.submitted?`<div class="question-feedback ${state.answers[i]!==q.answer?'needs-practice':''}"><strong>${state.answers[i]===q.answer?'You got it!':'A little learning moment.'}</strong> ${q.explanation}</div>`:''}</fieldset>`).join('')}<div class="quiz-actions">${state.submitted?`<button type="button" class="button secondary" data-retry="${g}-${l}">Try these questions again ${goArrow}</button>${button(`#/grade/${g}/level/${l}/results`,'Results & feedback')}`:`<p>No timer. No pressure. Just a chance to grow.</p><button type="submit" class="button">Check my results ${goArrow}</button>`}</div></form></div>`);}
function resultsPage(g,l){const state=stateFor(g,l),lesson=CURRICULUM[g].levels[l-1];if(!state.submitted)return levelShell(g,l,'results',`<div class="empty-results"><span aria-hidden="true">✧</span><h2>Your next lightbulb moment awaits.</h2><p>Complete the five exercise questions to see your score and feedback for every answer.</p>${button(`#/grade/${g}/level/${l}/exercises`,'Try the exercises')}</div>`);const score=scoreFor(g,l);const message=score===5?'Five out of five. You’re shining!':score>=3?'Look at you making progress!':'A great place to grow from.';return levelShell(g,l,'results',`<div class="result-page"><section class="result-summary" aria-live="polite"><div class="score-ring" style="--score:${score/5*100}%"><span>${score}/5<small>${score*20}% correct</small></span></div><div><span class="eyebrow">EVERY STEP COUNTS</span><h2>${message}</h2><p>${score===5?'You’ve got these ideas down. Ready for another discovery?':'Read the feedback below, revisit the lesson, and give it another go.'}</p><p>Best score: ${state.best}/5 · ${state.attempts} ${state.attempts===1?'attempt':'attempts'}</p></div></section><div class="result-buttons"><button class="button" data-retry="${g}-${l}">Try again <span aria-hidden="true">↻</span></button>${button(`#/grade/${g}/level/${l}/content`,'Revisit the lesson',true)}${button(l<3?`#/grade/${g}/level/${l+1}/content`:`#/grade/${g}`,l<3?'Next level':'Back to grade',true)}</div><h3>Your little learning moments</h3>${lesson.questions.map((q,i)=>{const correct=state.answers[i]===q.answer;return `<article class="review-card"><div class="review-title"><span class="review-mark ${correct?'':'wrong'}" aria-label="${correct?'Correct':'Incorrect'}">${correct?'✓':'↗'}</span><span>${i+1}. ${q.prompt}</span></div><p class="answer-line">Your answer: <strong>${q.options[state.answers[i]]}</strong>${correct?' · Correct!':` · Correct answer: <strong>${q.options[q.answer]}</strong>`}</p><p>${q.explanation}</p></article>`;}).join('')}</div>`);}
const toggle=document.getElementById('grade-toggle'), dropdown=document.getElementById('grade-dropdown');
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
function closeMenu(){toggle.setAttribute('aria-expanded','false');dropdown.hidden=true;}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));dropdown.hidden=open;});
document.addEventListener('click',e=>{if(!e.target.closest('.grade-menu'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dropdown.hidden){closeMenu();toggle.focus();}});
let initialRender=true;
function render(){
  closeMenu();const path=location.hash.slice(1)||'/';const parts=path.split('/').filter(Boolean);let html,title;
  if(path==='/'){html=home();title='Small steps. Big discoveries.';}
  else if(path==='/grades'){html=grades();title='Explore the grades';}
  else if(parts[0]==='grade'&&['6','7','8','9'].includes(parts[1])){const g=Number(parts[1]);if(parts.length===2){html=gradePage(g);title=`Grade ${g}`;}else if(parts.length===5&&parts[2]==='level'&&['1','2','3'].includes(parts[3])&&['content','exercises','results'].includes(parts[4])){const l=Number(parts[3]),tab=parts[4];html=({content:contentPage,exercises:exercisePage,results:resultsPage})[tab](g,l);title=`Grade ${g} · ${CURRICULUM[g].levels[l-1].title}`;}}
  if(!html){html=`<div class="container not-found"><h1>A little detour.</h1><p>That page isn’t on our map. Let’s find your next discovery.</p>${button('#/grades','Explore the grades')}</div>`;title='Page not found';}
  main.innerHTML=`<div class="view-enter">${html}</div>`;document.title=`${title} | Maths Club`;
  document.querySelector('.nav-home').classList.toggle('active',path==='/');document.querySelector('.grade-menu').classList.toggle('active',path!=='/');
  document.querySelector('.nav-home').toggleAttribute('aria-current',path==='/');if(path==='/')document.querySelector('.nav-home').setAttribute('aria-current','page');
  if(!initialRender){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}initialRender=false;
}
main.addEventListener('change',e=>{const input=e.target;if(!input.matches('#quiz input[type=radio]'))return;const form=input.closest('form'),g=Number(form.dataset.grade),l=Number(form.dataset.level),state=stateFor(g,l);if(state.submitted)return;state.answers[Number(input.dataset.question)]=Number(input.value);saveProgress();form.querySelectorAll(`input[name="${input.name}"]`).forEach(r=>r.closest('label').classList.toggle('selected',r.checked));document.getElementById('answered-counter').textContent=`${state.answers.filter(a=>a!==null).length} of 5 answered`;document.getElementById('quiz-validation').innerHTML='';});
main.addEventListener('submit',e=>{if(e.target.id!=='quiz')return;e.preventDefault();const g=Number(e.target.dataset.grade),l=Number(e.target.dataset.level),state=stateFor(g,l);if(state.submitted)return;const missing=state.answers.findIndex(a=>a===null);if(missing!==-1){document.getElementById('quiz-validation').innerHTML=`<p class="validation">You’re nearly there! Choose an answer for all five questions before checking your results.</p>`;const radio=document.querySelector(`#question-${missing} input`);radio.focus();radio.closest('fieldset').scrollIntoView({behavior:'smooth',block:'center'});return;}state.submitted=true;state.attempts++;state.best=Math.max(state.best,scoreFor(g,l));saveProgress();location.hash=`#/grade/${g}/level/${l}/results`;});
main.addEventListener('click',e=>{const retry=e.target.closest('[data-retry]');if(!retry)return;const [g,l]=retry.dataset.retry.split('-').map(Number),state=stateFor(g,l);state.answers=Array(5).fill(null);state.submitted=false;saveProgress();const next=`#/grade/${g}/level/${l}/exercises`;if(location.hash===next)render();else location.hash=next;});
window.addEventListener('hashchange',render);updateStorageNote();render();
